CURVATURE_SELECTION_SHA256 = '55e30b9a2ba99687f9641cf6a690a0cb52a78e300da95603fd12a9ed2df901e3'
CURVATURE_SOURCE_ONLY = True

def curvature_pins():
    assert sha256(json.dumps(CURVATURE_SELECTED,sort_keys=True,separators=(',',':')).encode()) == CURVATURE_SELECTION_SHA256, \
        'Exact finite curvature selection/provenance drift'
    snapshots = {}
    for commit, oid in CURVATURE_TREES.items():
        assert git('rev-parse',commit+'^{tree}').decode().strip() == oid, 'Finite curvature tree pin drift'
        snapshot = parse_tree(git('ls-tree','-rz',commit))
        assert len(snapshot) == CURVATURE_COUNTS[commit], 'Complete curvature source count drift'
        snapshots[commit] = snapshot
    assert set(CURVATURE_SELECTED) & set(snapshots[CURVATURE_PARENT]) == {'curvature/lakefile.toml'}
    assert len(CURVATURE_SELECTED) == 220
    for path, record in CURVATURE_SELECTED.items():
        assert len(record['origins']) == len({row['head'] for row in record['origins']})
        for origin in record['origins']:
            assert snapshots[origin['head']][path] == tuple(record['mode_blob'])
        data = git('show',record['origins'][0]['head']+':'+path)
        assert blob_id(data) == record['mode_blob'][1] and len(data) == record['bytes']
        assert sha256(data) == record['sha256']
    return snapshots

def curvature_section_inverse(raw, path, marker):
    start = ('# BEGIN authenticated finite curvature '+marker+'\n').encode()
    end = ('# END authenticated finite curvature '+marker+'\n').encode()
    assert raw.count(start) == raw.count(end) == 1, 'Curvature extension boundary drift'
    first = raw.index(start)
    last = raw.index(end, first)+len(end)
    restored = raw[:first]+raw[last:]
    if path == TEST:
        current_input_line = b'            expected = comp.curvature_identity(expected,originals,changes)[0]\n'
        assert restored.count(current_input_line) == 1, 'Finite current identity assertion extension drift'
        restored = restored.replace(current_input_line,b'',1)
        old_count = b'            self.assertEqual(len(expected), 1920)\n'
        new_count = b'            self.assertEqual(len(expected), 2139)\n'
        assert restored.count(new_count) == 1, 'Exact current identity count assertion drift'
        restored = restored.replace(new_count,old_count,1)
        old_unchanged = b'            unchanged = set(trees[FIXED_PARENT_PIN]) - comp.EDITED - comp.NEW - comp.FIXED_ROOTS - comp.TENSOR_PATHS\n'
        new_unchanged = old_unchanged.rstrip(b'\n')+b' - set(comp.CURVATURE_SELECTED)\n'
        assert restored.count(new_unchanged) == 1, 'Exact finite selected input assertion drift'
        restored = restored.replace(new_unchanged,old_unchanged,1)
        old_weighted = b'    def test_genuine_weighted_reconstruction_positive_and_adversarial_records(self):\n        import point4_weighted_hessian_release_guard as weighted\n        import stat\n        self.assertEqual(weighted.ROOT,comp.ROOT)\n        expected,originals,changes=self.inputs()\n'
        new_weighted = old_weighted.replace(b'expected,originals,changes=self.inputs()',b'expected,originals,changes=comp.curvature_identity(*self.inputs())')
        assert restored.count(new_weighted) == 1, 'Full-current genuine weighted fixture drift'
        restored = restored.replace(new_weighted,old_weighted,1)
        old_report = b"            self.assertEqual(report['public_paths'],1920)\n"
        new_report = b"            self.assertEqual(report['public_paths'],2139)\n"
        assert restored.count(new_report) == 1, 'Exact current weighted namespace count drift'
        restored = restored.replace(new_report,old_report,1)
        before = b'    suite.addTests(unittest.defaultTestLoader.loadTestsFromTestCase(TensorCompositionTests))\n'
        after = before+b'    suite.addTests(unittest.defaultTestLoader.loadTestsFromTestCase(CurvatureCompositionTests))\n'+b'    suite.addTests(unittest.defaultTestLoader.loadTestsFromTestCase(CurvatureProductionNamespaceTests))\n'
        assert restored.count(after) == 1, 'Finite curvature test-suite hook drift'
        restored = restored.replace(after,before,1)
    assert restored == git('show',CURVATURE_PARENT+':'+path), 'Complete curvature predecessor executable drift'
    return restored

