def tensor_identity(*args):
    result = _curvature_original_tensor_identity(*args)
    return curvature_identity(*result) if _curvature_verification_active else result

def tensor_helper_inverse(raw):
    return _curvature_original_helper_inverse(curvature_section_inverse(raw,HELPER,'extension'))

def tensor_test_inverse(raw):
    return _curvature_original_test_inverse(curvature_section_inverse(raw,TEST,'tests'))

def curvature_predecessor(expected, originals, changes, snapshots):
    parent = snapshots[CURVATURE_PARENT]
    assert len(expected) == len(parent) == 1920 and set(expected) == set(parent)
    curvature_section_inverse((ROOT/HELPER).read_bytes(),HELPER,'extension')
    curvature_section_inverse((ROOT/TEST).read_bytes(),TEST,'tests')
    old_helper = git('show',CURVATURE_PARENT+':'+HELPER)
    old_digest = sha256(old_helper)
    recovered = dict(expected)
    old_changes = {path:transform(path,originals[path],old_digest) for path in EDITED-{SMOOTH}}
    old_changes[SMOOTH] = transform(SMOOTH,originals[SMOOTH],old_digest,
        sha256(old_changes[FIXTURE]),sha256(old_changes[WORKFLOW]))
    for path in EDITED:
        assert (ROOT/path).read_bytes() == changes[path], 'Current curvature bootstrap bytes drift: '+path
        recovered[path] = ('100644',blob_id(old_changes[path]))
    for path in NEW:
        recovered[path] = parent[path]
    assert recovered == parent, 'Whole actual P source reconstruction drift'
    # Every immutable P mathematical/probe/dependency/workflow byte is recovered;
    # current digest-bound executable transforms are authenticated separately.
    return recovered

def curvature_identity(expected, originals, changes):
    snapshots = curvature_pins()
    curvature_predecessor(expected,originals,changes,snapshots)
    complete = dict(expected)
    for path, record in CURVATURE_SELECTED.items():
        data = curvature_selected_source(path)
        assert (ROOT/path).read_bytes() == data, 'Current finite curvature input source drift: '+path
        complete[path] = (record['mode_blob'][0],blob_id(data))
    assert len(complete) == 2139 and len({path.casefold() for path in complete}) == 2139
    return complete,originals,changes

def tensor_map_record(expected, originals, changes):
    snapshots = curvature_pins()
    legacy = {path:expected[path] for path in snapshots[CURVATURE_PARENT]}
    legacy['curvature/lakefile.toml'] = snapshots[CURVATURE_PARENT]['curvature/lakefile.toml']
    complete,_,_ = curvature_identity(legacy,originals,changes)
    assert expected == legacy or expected == complete, 'Unknown finite curvature map input'
    record = _curvature_original_tensor_map_record(legacy,originals,changes)
    record['curvature_finite_input_preparation'] = {
        'parent':CURVATURE_PARENT,'parent_tree':CURVATURE_TREES[CURVATURE_PARENT],
        'source_trees':dict(CURVATURE_TREES),'source_counts':dict(CURVATURE_COUNTS),
        'selected_sources':CURVATURE_SELECTED,
        'complete_input_paths':2139,'current_incoming_guard_wiring':'UNQUALIFIED finite executable adapters',
        'native_qualification':'UNRUN','point4':'OPEN',
        'executable_transforms':sorted(CURVATURE_EXECUTABLE_PATHS),
        'scope':'Original mathematical inputs unchanged; exact reversible executable adapters require separate current/Linux/native qualification.'}
    record['paths'] = len(complete)
    record['identity'] = {path:([complete[path][0],'<committed-HEAD>'] if path==MAP else list(complete[path]))
                          for path in sorted(complete)}
    return record

def tensor_reconstructed_sources(namespace, inherited, expected):
    result = _curvature_original_reconstructed_sources(namespace,inherited,expected)
    path = 'curvature/lakefile.toml'
    if path in result:
        parent = curvature_pins()[CURVATURE_PARENT]
        assert blob_id(result[path][1]) == parent[path][1], 'Original curvature configuration record drift'
        record = CURVATURE_SELECTED[path]
        assert expected[path] == tuple(record['mode_blob'])
        data = (ROOT/path).read_bytes()
        assert sha256(data) == record['sha256'] and blob_id(data) == expected[path][1]
        result[path] = ('current-curvature-exact-input-composition',data)
    return result

def verify_current():
    global _curvature_verification_active
    assert re.fullmatch(r'[0-9a-f]{40}',FIXED_PARENT or ''), 'Actual repaired PR115 commit pin is required'
    assert _curvature_verification_active is False, 'Recursive finite curvature verification forbidden'
    for commit in CURVATURE_TREES:
        subprocess.run(['git','--no-replace-objects','-C',str(ROOT),'merge-base','--is-ancestor',commit,'HEAD'],
                       check=True,env=ENV)
    # The entire preceding verifier body still runs on the exact finite current
    # namespace, including real HEAD/index/physical/mode/cache/dependency/map gates.
    # A separate nonreentrant identity mode leaves the original replacement-owner
    # policy intact when that body enters the genuine weighted inventory namespace.
    _curvature_verification_active = True
    try:
        result = _curvature_original_verify_current()
    finally:
        _curvature_verification_active = False
    assert len(result) == 2139
    return result
