def curvature_chart_current_body(namespace):
    """Clone the immutable admission body with four explicit historical deltas.

    All live HEAD/index/physical/dependency/provenance/closure/type policies
    continue on the actual current root. The old complete source-delta view
    has its own authenticated name and scope. No source view is fabricated.
    """
    import ast
    original=git('show',CURVATURE_CHART_HEAD+':'+CURVATURE_CHART_PATH)
    selected=CURVATURE_SELECTED[CURVATURE_CHART_PATH]
    assert blob_id(original)==selected['mode_blob'][1] and sha256(original)==selected['sha256']
    node,=[item for item in ast.parse(original).body if isinstance(item,ast.FunctionDef) and item.name=='admit']
    raw=ast.get_source_segment(original.decode(),node)+'\n'
    anchor='    base, current = tree_entries(root, BASE), tree_entries(root, \'HEAD\')\n'
    added=anchor+('    _curvature_comp=globals()[\'_curvature_comp\']\n'
        '    assert pathlib.Path(root).resolve()==_curvature_comp.ROOT\n'
        '    _curvature_current=_curvature_comp.verify_current()\n'
        '    assert current=={p:(mode,\'blob\',oid) for p,(mode,oid) in _curvature_current.items()}\n'
        '    _curvature_historical=tree_entries(root,\'003f2a3e980a4a82399dc5ee5b581a181cb61652\')\n'
        '    assert _curvature_historical=={p:(mode,\'blob\',oid) for p,(mode,oid) in _curvature_comp.curvature_pins()[\'003f2a3e980a4a82399dc5ee5b581a181cb61652\'].items()}\n')
    replacements=[(anchor,added),
        ('set(current) - set(dependent) == extension_paths','set(_curvature_historical) - set(dependent) == extension_paths'),
        ('{path for path in dependent if dependent[path] != current[path]} == RICCI_MODIFIED_PATHS',
         '{path for path in dependent if dependent[path] != _curvature_historical[path]} == RICCI_MODIFIED_PATHS'),
        ('set(current) - set(base) == new_paths | EXTRA | extension_paths',
         'set(_curvature_historical) - set(base) == new_paths | EXTRA | extension_paths'),
        ("[p for p in base if base[p] != current[p]] == ['curvature/lakefile.toml']",
         "[p for p in base if base[p] != _curvature_historical[p]] == ['curvature/lakefile.toml']"),
        ("    return dict(candidate_sha=expected_sha, candidate_tree=expected_tree, base=BASE, base_tree=BASE_TREE,\n",
         "    assert _curvature_comp.verify_current()==_curvature_current, 'Current chart source POST drift'\n"
         "    return dict(candidate_sha=expected_sha, candidate_tree=expected_tree, base=BASE, base_tree=BASE_TREE,\n"
         "                complete_current_public_paths=len(_curvature_current), historical_source_delta_head='003f2a3e980a4a82399dc5ee5b581a181cb61652',\n"),
        ("additions=len(new_paths | EXTRA | extension_paths), modified_paths=['curvature/lakefile.toml'],",
         "historical_additions=len(new_paths | EXTRA | extension_paths), historical_modified_paths=['curvature/lakefile.toml'],"),
        ('inherited_paths=len(base), all_inherited_validators_unchanged=True,',
         "historical_inherited_paths=len(base), all_inherited_validators_unchanged=False, current_source_identity='Complete separately authenticated finite composition',")]
    changed=raw
    for before,after in replacements:
        assert changed.count(before)==1, 'Exact chart admission seam drift'
        changed=changed.replace(before,after,1)
    recovered=changed
    for before,after in reversed(replacements):
        assert recovered.count(after)==1
        recovered=recovered.replace(after,before,1)
    assert recovered==raw, 'Whole immutable chart admission body not recovered'
    # The clone receives the separately authenticated original policy bindings;
    # its unchanged live predicates retain their genuine actual-root globals.
    assert namespace['_curvature_comp'] is sys.modules[__name__]
    scope=dict(namespace)
    scope['pathlib']=pathlib
    exec(compile(changed,str(ROOT/CURVATURE_CHART_PATH),'exec',dont_inherit=True),scope)
    clone=scope['admit']
    assert clone.__globals__ is scope
    return clone

def curvature_chart_current(namespace,root,expected_sha,expected_tree,dependencies=None):
    # This template remains unqualified until its namespace binding, exact
    # finite transform, all actual-current controls and native run are reviewed.
    curvature_chart_namespace_binding(namespace)
    model=verify_current();primary=None
    try:
        body=curvature_chart_current_body(namespace)
        return body(root,expected_sha,expected_tree,dependencies)
    except BaseException as error:
        primary=error;raise
    finally:
        try:
            curvature_chart_namespace_binding(namespace)
            assert verify_current()==model, 'Current chart complete-source POST drift'
        except BaseException as error:
            if primary is None:raise
            primary.add_note('Current chart POST also failed: '+repr(error))
# END exact current curvature chart admission
